-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 04', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 04 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-04.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Cite as temperaturas aproximadas do bico e da mesa e explique por que o colega não deve tocar neles logo após o uso.', 0.33, 'O bico fica a cerca de 200 °C e a mesa a cerca de 60 °C. Tocar neles com a impressora ligada ou logo após o uso causa queimadura, porque continuam quentes por um tempo.', 'Nota cheia: cita as duas temperaturas aproximadas (bico perto de 200 °C, mesa perto de 60 °C) e o risco de queimadura. Metade: só as temperaturas ou só o risco. Zero: sem relação.'),
      (v_atividade, 1, 2, 'Aponte duas outras condutas erradas do colega e diga o que ele deveria fazer em cada uma.', 0.33, 'Cordão solto: prender o cabelo e tirar pulseiras e cordões para não enroscar nas peças móveis. Abrir a máquina em funcionamento: não mexer na máquina ligada e operar somente com o professor presente, avisando-o antes.', 'Nota cheia: duas condutas erradas com a correção certa de cada uma. Metade: uma conduta com a correção, ou duas sem correção. Zero: nenhuma conduta correta.'),
      (v_atividade, 1, 3, 'Explique como e quando a peça deve ser retirada da mesa com segurança.', 0.34, 'A peça deve ser retirada com a mesa fria (ou com espátula), com o ambiente ventilado e longe do rosto, depois que a impressora esfriar.', 'Nota cheia: indica a mesa fria (ou espátula) e o cuidado de afastar o rosto/ventilar. Metade: só um desses. Zero: sugere retirar a peça quente com a mão.'),
      (v_atividade, 2, 1, 'Indique a ordem em que os três pedidos devem ser impressos, seguindo a regra da oficina.', 0.33, 'Primeiro o chaveiro de 20 minutos, depois a peça de 25 minutos (as duas até 30 minutos) e por último a peça do projeto final da equipe.', 'Nota cheia: as peças rápidas (até 30 minutos) antes da peça longa do projeto final. Metade: ordem correta entre as rápidas mas peça longa fora do fim, ou o contrário. Zero: ordem invertida ou sem regra.'),
      (v_atividade, 2, 2, 'Explique o motivo dessa regra para a turma.', 0.33, 'As peças rápidas liberam a máquina logo e permitem que mais alunos imprimam; a peça longa de cada equipe fica por último para não prender a fila e a turma esperar horas.', 'Nota cheia: cita que as peças rápidas liberam a máquina/atendem mais alunos e que a peça longa atrasaria a fila. Metade: cita só um desses pontos. Zero: sem relação com a fila.'),
      (v_atividade, 2, 3, 'Diga quem deve estar presente enquanto as máquinas imprimem e o que os alunos não devem fazer com a impressora em funcionamento.', 0.34, 'O professor deve estar presente durante a operação. Os alunos não devem abrir nem mexer na máquina em funcionamento.', 'Nota cheia: cita o professor presente e a proibição de abrir/mexer na máquina em funcionamento. Metade: só um. Zero: nenhum.'),
      (v_atividade, 3, 1, 'Explique o que é o bico e qual é a sua função durante a impressão.', 0.33, 'O bico é a ponta aquecida por onde o plástico derretido sai e é depositado, camada por camada, para formar a peça.', 'Nota cheia: explica que o bico derrete/libera o plástico e deposita as camadas. Metade: só diz que é por onde sai o plástico. Zero: função errada.'),
      (v_atividade, 3, 2, 'Explique o que faz o extrusor e o que é a mesa de impressão.', 0.33, 'O extrusor empurra o filamento até o bico. A mesa é a superfície onde a peça é construída e fica apoiada durante a impressão.', 'Nota cheia: explica o extrusor (empurra o filamento) e a mesa (superfície de apoio da peça). Metade: só um dos dois. Zero: trocados ou errados.'),
      (v_atividade, 3, 3, 'Diga para que servem os eixos e o painel da impressora.', 0.34, 'Os eixos movimentam o bico e/ou a mesa nas direções da impressão. O painel é onde o operador controla a máquina (aquecer, carregar filamento, iniciar ou parar a impressão).', 'Nota cheia: função dos eixos (movimento) e do painel (controle). Metade: só um. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Explique o que significa nivelar a mesa.', 0.33, 'Nivelar a mesa é ajustar a distância entre o bico e a mesa para que fique correta e igual em toda a superfície, para o plástico aderir bem.', 'Nota cheia: fala em ajustar a distância entre bico e mesa para a primeira camada aderir. Metade: ideia vaga ("deixar a mesa certa"). Zero: errado.'),
      (v_atividade, 4, 2, 'Descreva como usar uma folha de papel para conferir a distância entre o bico e a mesa e qual resultado indica o ajuste certo.', 0.33, 'Colocar uma folha de papel entre o bico e a mesa e arrastá-la; o ajuste está certo quando a folha passa com leve atrito.', 'Nota cheia: usa a folha de papel arrastada e indica o leve atrito como resultado certo. Metade: cita o papel sem o resultado. Zero: método errado.'),
      (v_atividade, 4, 3, 'Diga o que acontece com as linhas de plástico se o bico estiver alto demais e como a limpeza da mesa com álcool isopropílico ajuda a peça.', 0.34, 'Com o bico alto demais, as linhas de plástico saem separadas e falta plástico/aderência. A mesa limpa com álcool isopropílico melhora a aderência da peça.', 'Nota cheia: linhas separadas/falta de plástico com bico alto e limpeza com álcool melhora a aderência. Metade: só um. Zero: nenhum.'),
      (v_atividade, 5, 1, 'Escreva, em ordem, os passos para carregar o filamento, do aquecimento do bico até o plástico sair.', 0.33, '1) Aquecer o bico. 2) Inserir o filamento no extrusor. 3) Purgar até o plástico sair uniforme.', 'Nota cheia: os três passos na ordem certa. Metade: dois passos ou ordem trocada. Zero: um ou nenhum.'),
      (v_atividade, 5, 2, 'Explique o que é purgar o filamento e como saber que a purga foi bem-feita.', 0.33, 'Purgar é empurrar filamento até sair plástico pelo bico; está bem-feito quando o plástico sai uniforme, sem falhas nem cor misturada do filamento anterior.', 'Nota cheia: explica o que é purgar e que o plástico deve sair uniforme. Metade: só um. Zero: errado.'),
      (v_atividade, 5, 3, 'Explique por que o bico precisa estar aquecido antes de inserir o filamento.', 0.34, 'Porque o filamento só amolece/derrete quente; com o bico frio ele não passa e pode travar ou danificar o extrusor.', 'Nota cheia: explica que o plástico precisa estar mole/derretido para passar. Metade: diz só "para funcionar melhor". Zero: sem relação.'),
      (v_atividade, 6, 1, 'Descreva como deve ser uma primeira camada bem calibrada.', 0.33, 'Deve sair achatada, uniforme e bem aderida à mesa.', 'Nota cheia: cita as três características (achatada, uniforme, aderida). Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 6, 2, 'Explique por que a primeira camada é tão importante para a peça inteira.', 0.33, 'Porque é a base da peça: se ela falha, as camadas seguintes também falham e a peça pode soltar ou sair estragada; é a camada que decide o sucesso da peça.', 'Nota cheia: explica que as demais camadas dependem dela/a peça falha se ela falha. Metade: repete a frase sem explicar. Zero: sem relação.'),
      (v_atividade, 6, 3, 'Diga o que fazer com essa impressão agora e justifique a decisão.', 0.34, 'Interromper a impressão na hora, reajustar o nivelamento e imprimir de novo, para não gastar horas de filamento numa peça que vai falhar.', 'Nota cheia: decide parar e justifica pela economia de filamento/tempo ou pela peça que falharia. Metade: para sem justificar. Zero: manda continuar.'),
      (v_atividade, 7, 1, 'Dê o nome desse defeito e aponte duas prováveis causas.', 0.33, 'Empenamento (peça solta da mesa ou cantos levantados). Causas: mesa suja ou fria; pouca aderência.', 'Nota cheia: nome do defeito e duas causas (mesa suja, mesa fria/pouca aderência). Metade: nome com uma causa, ou duas causas sem o nome. Zero: errado.'),
      (v_atividade, 7, 2, 'Indique duas ações de correção, uma na preparação da mesa e uma no fatiador.', 0.33, 'Na preparação: limpar a mesa (álcool isopropílico) e aquecê-la. No fatiador: usar borda (brim).', 'Nota cheia: uma ação de preparação e uma do fatiador, certas. Metade: só uma ação certa. Zero: nenhuma.'),
      (v_atividade, 7, 3, 'Explique para que serve a borda (*brim*) e como ela ajuda a peça.', 0.34, 'A borda (brim) é uma aba extra impressa em volta da peça na primeira camada; aumenta a área de contato com a mesa e melhora a aderência, evitando que os cantos levantem.', 'Nota cheia: explica que aumenta a área/aderência e evita o levantamento. Metade: diz só que "ajuda a colar". Zero: errado.'),
      (v_atividade, 8, 1, 'Aponte duas prováveis causas desse defeito.', 0.33, 'Bico alto demais (longe da mesa) ou bico entupido.', 'Nota cheia: as duas causas. Metade: uma. Zero: nenhuma.'),
      (v_atividade, 8, 2, 'Indique a correção para cada uma das causas.', 0.33, 'Bico alto: reajustar o nivelamento. Bico entupido: limpar o bico.', 'Nota cheia: a correção certa para cada causa. Metade: uma correção certa. Zero: nenhuma.'),
      (v_atividade, 8, 3, 'Diga o que fazer com a impressão em andamento antes de corrigir o problema.', 0.34, 'Interromper a impressão, pois a peça já está falhando e continuar desperdiça filamento e tempo; só depois corrigir e imprimir de novo.', 'Nota cheia: indica parar e justifica. Metade: indica parar sem justificar. Zero: manda continuar.'),
      (v_atividade, 9, 1, 'Diga o nome desse defeito e o que ele é.', 0.33, 'Stringing: fios finos de plástico que ficam entre as partes da peça.', 'Nota cheia: nome (stringing/fios entre partes) e a descrição. Metade: só um. Zero: errado.'),
      (v_atividade, 9, 2, 'Indique as duas causas prováveis e a configuração do fatiador que reduz o problema.', 0.33, 'Causas: temperatura alta ou retração baixa. Correção no fatiador: reduzir a temperatura e ajustar (aumentar) a retração.', 'Nota cheia: as duas causas e a configuração (temperatura/retração). Metade: só uma causa ou só a configuração. Zero: nenhuma.'),
      (v_atividade, 9, 3, 'Diga como você registraria o ajuste para conferir o resultado na impressão seguinte.', 0.34, 'Anotar na ficha a configuração usada (temperatura e retração), a falha observada e o ajuste feito, e comparar com o resultado da nova impressão.', 'Nota cheia: registra configuração, falha e ajuste e compara com o novo resultado. Metade: registra parte. Zero: não registra.'),
      (v_atividade, 10, 1, 'Indique a provável causa e a correção para o deslocamento de camadas.', 0.33, 'Causa provável: correia solta ou velocidade alta. Correção: conferir as correias e reduzir a velocidade.', 'Nota cheia: causa e correção certas. Metade: só uma delas certa. Zero: nenhuma.'),
      (v_atividade, 10, 2, 'Indique a provável causa e a correção para os suportes difíceis de remover.', 0.33, 'Causa provável: orientação ruim da peça. Correção: reorientar a peça e refatiar.', 'Nota cheia: causa (orientação) e correção (reorientar e refatiar). Metade: só uma. Zero: nenhuma.'),
      (v_atividade, 10, 3, 'Monte a ficha de entrega da aula: liste três informações que devem ser registradas sobre a impressão.', 0.34, 'A configuração usada, as falhas observadas e os ajustes feitos (e o resultado da impressão).', 'Nota cheia: três informações certas da ficha. Metade: duas. Zero: uma ou nenhuma.');
end $$;
